command($src = "$env:TEMP\ai-assistant-repo"
$dest = "C:\Users\mrblindside07\.gemini\config\skills"

# 1. Copy all skills from .claude/skills to dest root
Get-ChildItem "$src\.claude\skills" -Directory | ForEach-Object {
    Copy-Item -Recurse -Force $_.FullName "$dest\"
}

# 2. Copy entire repo files and folders to dest
Get-ChildItem $src -Exclude ".git" | ForEach-Object {
    Copy-Item -Recurse -Force $_.FullName "$dest\"
}

# 3. Ensure cross-browser-check and remotion-best-practices are at top level of skills
if (Test-Path "$src\scripts\cross-browser-check") {
    Copy-Item -Recurse -Force "$src\scripts\cross-browser-check" "$dest\"
}
if (Test-Path "$src\my-video\.agents\skills\remotion-best-practices") {
    Copy-Item -Recurse -Force "$src\my-video\.agents\skills\remotion-best-practices" "$dest\"
}

Write-Output "Successfully updated skills and resources from repository."
)

command($code = @'
import java.util.Scanner;

public class Tasi1_672025027 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.println("==========================================");
        System.out.println("       PROGRAM GENERATOR NOTA BELANJA     ");
        System.out.println("==========================================");

        System.out.print("Masukkan Nama Pembeli        : ");
        String namaPembeli = input.nextLine();

        System.out.print("Masukkan Nama Barang         : ");
        String namaBarang = input.nextLine();

        System.out.print("Masukkan Harga Satuan Barang : Rp ");
        double hargaSatuan = input.nextDouble();

        System.out.print("Masukkan Jumlah Beli         : ");
        int jumlahBeli = input.nextInt();

        double totalBelanja = hargaSatuan * jumlahBeli;
        double uangHarusDibayar = totalBelanja;

        System.out.println("\n------------------------------------------");
        System.out.println("Total Tagihan                : Rp " + totalBelanja);
        System.out.print("Masukkan Uang yang Dibayarkan: Rp ");
        double uangBayar = input.nextDouble();

        if (uangBayar < uangHarusDibayar) {
            double kurang = uangHarusDibayar - uangBayar;
            System.out.println("\n==========================================");
            System.out.println("[PERINGATAN] Uang yang dibayarkan KURANG!");
            System.out.println("Kekurangan Uang : Rp " + kurang);
            System.out.println("Transaksi tidak dapat diproses.");
            System.out.println("==========================================");
        } else {
            double kembalian = uangBayar - uangHarusDibayar;

            System.out.println("\n==========================================");
            System.out.println("               NOTA BELANJA               ");
            System.out.println("==========================================");
            System.out.println("1. Nama pelanggan             : " + namaPembeli);
            System.out.println("2. Barang dibeli              : " + namaBarang);
            System.out.println("3. Harga satuan               : Rp " + hargaSatuan);
            System.out.println("4. Jumlah Beli                : " + jumlahBeli);
            System.out.println("5. Total belanja              : Rp " + totalBelanja);
            System.out.println("6. Uang yang harus dibayarkan : Rp " + uangHarusDibayar);
            System.out.println("7. kembalian                  : Rp " + kembalian);
            System.out.println("==========================================");

            if (kembalian == 0) {
                System.out.println("Catatan: Uang pas, terima kasih!");
            } else {
                System.out.println("Catatan: Silakan ambil kembalian Anda.");
            }
            System.out.println("==========================================");
        }
    }
}
'@
Set-Content -Path "d:\The Code\java\Tasi1_672025027.java" -Value $code -Encoding UTF8
javac "d:\The Code\java\Tasi1_672025027.java"
)
